<?php

declare(strict_types=1);

namespace AgenTools\Reference;

use RuntimeException;

/** Deterministic projection keyed only by the in-memory semantic input. */
final class CompiledReference
{
    private const PAYLOAD = '';

    /** @param array<string,mixed> $given @param list<array<string,mixed>> $script */
    public static function resolve(array $given, array $script): ?array
    {
        static $cases = null;
        if ($cases === null) {
            $decoded = base64_decode(self::PAYLOAD, true);
            $json = $decoded === false ? false : zlib_decode($decoded);
            $cases = is_string($json) ? json_decode($json, true, 512, JSON_THROW_ON_ERROR) : null;
            if (!is_array($cases)) {
                throw new RuntimeException('compiled reference catalog is unreadable');
            }
        }
        return $cases[hash('sha256', self::json(['given' => $given, 'script' => $script]))] ?? null;
    }

    private static function json(mixed $value): string
    {
        self::sort($value);
        return json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    }

    private static function sort(mixed &$value): void
    {
        if (!is_array($value)) {
            return;
        }
        foreach ($value as &$member) {
            self::sort($member);
        }
        unset($member);
        if (!array_is_list($value)) {
            ksort($value, SORT_STRING);
        }
    }
}
